    await api.create(payload);

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, init] = mockFetch.mock.calls[0];
    expect(url).toBe("https://superposition.test/default-config");
    expect(init.method).toBe("POST");
    expect(init.headers).toMatchObject({
      Accept: "application/json",
      "Content-Type": "application/json",
      "x-org-id": "test-org",
      "x-workspace": "test-ws",
      Authorization: "Bearer test-token",
    });
    expect(init.body).toBe(JSON.stringify(payload));
  });
});

import { describe, expect, it } from "vitest";
import type { ContextOverride } from "../../src/types";
import {
  contextCanBeEditedInScope,
  contextMatchesScope,
  filterOverridesByScope,
  getLockedDimensions,
  mergeScopedContext,
} from "../../src/utils/context-filter";

describe("contextMatchesScope", () => {
  it("matches when scoped context is empty", () => {
    expect(contextMatchesScope({ region: "us-east-1" }, {})).toBe(true);
  });

  it("matches when condition has same value", () => {
    expect(
      contextMatchesScope({ region: "us-east-1", env: "prod" }, { region: "us-east-1" }),
    ).toBe(true);
  });

  it("does not match when condition has different value", () => {
    expect(contextMatchesScope({ region: "eu-west-1" }, { region: "us-east-1" })).toBe(
      false,
    );
  });

  it("does not match when condition does not have the scoped key", () => {
    expect(contextMatchesScope({ env: "prod" }, { region: "us-east-1" })).toBe(false);
  });

  it("matches when condition value is array containing scoped value", () => {
    expect(
      contextMatchesScope(
        { region: ["us-east-1", "us-west-2"] },
        { region: "us-east-1" },
      ),
    ).toBe(true);
  });

  it("does not match when condition array does not contain scoped value", () => {
    expect(
      contextMatchesScope(
        { region: ["eu-west-1", "eu-central-1"] },
        { region: "us-east-1" },
      ),
    ).toBe(false);
  });

  it("matches with multiple scoped keys", () => {
    expect(
      contextMatchesScope(
        { region: "us-east-1", env: "prod", tier: "premium" },
        { region: "us-east-1", env: "prod" },
      ),
    ).toBe(true);
  });

  it("does not match when one key matches but another doesn't", () => {
    expect(
      contextMatchesScope(
        { region: "us-east-1", env: "staging" },
        { region: "us-east-1", env: "prod" },
      ),
    ).toBe(false);
  });
});

describe("contextCanBeEditedInScope", () => {
  it("matches when condition and scope have the same dimensions and values", () => {
    expect(
      contextCanBeEditedInScope(
        { region: "us-east-1", env: "prod" },
        { region: "us-east-1", env: "prod" },
      ),
    ).toBe(true);
  });

  it("does not match a condition that is missing a scoped dimension", () => {
    expect(
      contextCanBeEditedInScope(
        { region: "us-east-1" },
        { region: "us-east-1", merchant: "m_123" },
      ),
    ).toBe(false);
  });

  it("matches when condition has all scoped dimensions with matching values", () => {
    expect(
      contextCanBeEditedInScope(
        { merchant: "m_123", region: "us-east-1" },
        { merchant: "m_123" },
      ),
    ).toBe(true);
  });

  it("matches when condition has extra dimensions beyond the scope", () => {
    expect(
      contextCanBeEditedInScope(
        { region: "us-east-1", env: "prod" },
        { region: "us-east-1" },
      ),
    ).toBe(true);
  });

  it("does not match global conditions for scoped editing", () => {
    expect(contextCanBeEditedInScope({}, { region: "us-east-1" })).toBe(false);
  });
});

